from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
m.lesson(13,'Pagbasa ng scale at kahulugan ng mga guhit sa drawing','Ihiwalay ang kahulugan ng scale at gamit ng guhit at tiyakin ang kondisyon ng paggawa mula sa nakasulat na dimensiyon.',[
('Laki ng larawan at dimensiyon ng tunay na bagay','Ang full scale1:1ay parehong laki ng tunay, enlarged2:1ay doble, at reduced1:2ay kalahati. Kahit doble ang larawan, hindi nadodoble ang nakasulat na dimensiyon. Basahin ang dimensiyon bilang tunay na sukat ng bagay.\nMaaaring magbago ang laki sa photocopy o screen. Huwag gawing sukat ng produkto ang nakuha sa paglalagay ng ruler sa screen o print. Suriin ang dimensiyon, yunit, tala, at rebisyon at magtanong bago magproseso kung hindi malinaw.'),
('Ang guhit ay nagpapakita ng nakikita at gamit','Ginagamit ang makapal na solid line para sa nakikitang outline, manipis na solid para sa dimension line, manipis na chain na isang dash-isang dot para sa center, at dashed para sa nakatagong bahagi. Kahit magkahawig, magkaiba ang kahulugan ayon sa kapal at uri. Huwag ipagkamali ang center line ng butas sa outline na dapat putulin.\nMaaaring hindi makita ang nakatagong bahagi o reference face sa pagpapalaki lamang ng isang bahagi. Itugma ang kaugnay na view, section, at tala at tiyakin mula sa aling face hanggang saan ang dimensiyon bago magtrabaho.'),
('Kalkulasyon ng scale at pasya sa trabaho','Kung1:5ang pang-aral na drawing at80 mmang tunay na lapad,80÷5=16 mmang nasa drawing. Ngunit maaaring hindi na16 mmang ruler kapag muling pinaliit ang photocopy. Ang batayan ng tunay na lapad ay nakasulat na80 mm. Huwag palitan ang lapad ng materyal dahil lamang maliit tingnan ang drawing.')],['Ratio ng haba sa drawing sa haba ng tunay na bagay.','Scale na mas malaki ang drawing kaysa tunay na bagay.','Scale na mas maliit ang drawing kaysa tunay na bagay.','Guhit na nagpapakita ng center o axis ng hugis.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7scale,7drawing checklist,3paglalagom.\nPagsulat:Kunin ang haba sa drawing ng tunay na45 mm sa2:1at1:2. Gumawa ng talaan ng gamit ng outline, dimension, center, at hidden lines. Sumulat sa Japanese ng hiling sa pagtiyak kapag iba ang nasukat sa screen sa nakasulat na dimensiyon.\nSariling pagsusuri:Nakukuha ba ang90 mm at22.5 mm at naipapaliwanag na45 mm pa rin ang tunay?',['Huwag magsimula batay sa hula kung kulang ang dimensiyon o hindi malinaw ang rebisyon.','Huwag itakda ang butas o putol habang malabo ang pagbasa ng guhit.'],'Ratio ng pagguhit ang scale at hindi nito binabago ang sukat ng produkto. Basahin nang sabay ang uri ng guhit at reference ng dimensiyon.')
m.lesson(14,'Pagpili sa layout drawing at connection diagram','Ihiwalay ang pisikal na ayos at electrical connection at itugma sa mga drawing ang piyesa at terminal.',[
('Drawing ayon sa gustong malaman','Sa layout, suriin kung saan ilalagay ang kagamitan at paano maglalaan ng puwang para sa pagkabit at maintenance. Sa connection diagram, tiyakin kung aling kagamitan o terminal ang ikakabit saan. Hindi laging sunod-sunod na daloy ng kuryente ang posisyon sa drawing.\nGinagamit ang system diagram para sa kabuuang electrical system at circuit o developed connection diagram para maunawaan ang ugnayan ng operasyon. Maaaring magkaiba ayon sa lugar ang tawag at pagpapahayag; suriin ang pamagat, legend, at tala.'),
('Sundan gamit ang pangalan at terminal number','Kapag maraming sheet, itugma gamit ang parehong equipment symbol, part number, at terminal number. Huwag ikonekta dahil lamang magkalapit ang drawing. Kahit magkahawig ang pangalan ng destinasyon, ibang koneksiyon kung iba ang numero o signal.\nMaaaring magkahalo ang lumang standard at industry symbols. Huwag tiyakin mula sa iisang kabisadong hugis; tingnan ang standard at legend ng drawing. Basahin kasama ang kondisyon ng kagamitan ang batayang a-contact na nagsasara sa pag-actuate at b-contact na bumubukas sa pag-actuate.'),
('Kapag hindi tugma ang mga drawing','Kahit nasa kaliwa ang terminal blockTB2sa layout, kungTB1-3ang destinasyon sa connection diagram, huwag ikabit saTB2dahil nasa kaliwa. Suriin ang rebisyon at equipment symbol at i-hold ang koneksiyon hanggang malutas ang salungatan. Kailangang pagtugmain ang aktuwal na ayos, pagkakakilanlan ng piyesa, at destinasyon.')],['Drawing ng ugnayan ng posisyon ng piyesa o kagamitan.','Drawing ng electrical connection ng kagamitan o terminal.','Numerong kumikilala sa terminal na ikakabit.','Bahaging nagpapaliwanag ng simbolo at pagpapahayag sa drawing.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7salungatang drawing,7tala ng pagtutugma,3paglalagom.\nPagsulat:Ayusin kung aling drawing ang gamit sa “lugar ng piyesa,” “koneksiyon ng terminal,” at “kabuuang power system.” Ilista ang rebisyon, equipment symbol, at terminal number na susuriin kung hindi tugma angTB1-3atTB2-3.\nSariling pagsusuri:May pamamaraan ba sa paglutas ng salungatan at hindi basta ikinokonekta ang malapit na piyesa?',['Ihambing ang drawing sa de-energized na pang-aral o aprubadong kondisyon; huwag basta baguhin ang wiring ng aktuwal na kagamitan.','Huwag ipalit sa safety contact ang ibang uri dahil lamang magkahawig ang operasyon.'],'Layout: lugar; connection: electrical relation. Itugma ang mga drawing gamit ang equipment symbol at terminal number.')
m.lesson(15,'Pagpili ng conductive, magnetic, at insulating materials','Ihiwalay ang papel at kondisyon ng materyal at isama ang errata sa pag-uuri ng insulating materials.',[
('Huwag ipaghalo ang tatlong papel','Conductive material ang ginagamit sa bahaging dinadaluyan ng current; ang copper at aluminum ay ginagamit sa wire ayon sa layunin. Magnetic material ang nasa bahaging gumagamit ng magnetism, gaya ng core ng transformer. Ang insulator ay mahirap daluyan at naghihiwalay sa conductors. Kahit sa isang piyesa, kailangan ang magkakaibang materyal.\nHindi laging pinakamainam sa lahat ng kondisyon ang mataas na conductivity. Tiyakin din ang timbang, machinability, temperatura, mechanical strength, at paraan ng koneksiyon. Kahit conductive ang aluminum, hindi ito maaaring ituring na magnetic material na katulad ng iron.'),
('Hindi pangalan lamang ang garantiya ng insulation','Nagbabago rin ang performance ng insulator dahil sa sobrang init, dumi, gasgas, at pagtanda. Tingnan sa espesipikasyon ang heat class, temperatura, kapaligiran, at kailangang kapal. Huwag sabihing ligtas dahil mukhang resin o rubber.\nKasama rito ang errata noong2026taon10buwan1araw. Alisin ang “natural rubber” sa inorganic insulation examples sa printed page70ng orihinal naPDF; mica at ceramic ang inorganic examples. Huwag isaulo na inorganic ang natural rubber.'),
('Halimbawa ng pagpili ayon sa papel','Sa modelong transformer, iba ang papel ng winding na dinadaluyan, core na dinaraanan ng magnetic flux, at insulation na naghihiwalay sa winding. Gumamit ng conductive material sa winding, angkop na magnetic material sa core, at insulator sa pagitan. Sa espesipikasyon itinatakda ang partikular na materyal at temperature rating; huwag pumili ng kapalit sa tunay na produkto mula lamang sa paliwanag ng modelo.')],['Materyal na ginagamit upang magdaloy ng kuryente.','Materyal na gumagamit ng epekto ng magnetism.','Materyal na mahirap daluyan ng kuryente at naghihiwalay sa conductors.','Katangiang nagpapanatili ng performance laban sa init.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7halimbawa ng papel,7paghahambing ng materyal,3paglalagom.\nPagsulat:Gumawa ng talaan ng papel at kundisyong susuriin sa winding, core, at insulation. Piliin sa natural rubber, mica, at ceramic ang inorganic examples at ipaliwanag kung bakit hindi kasama ang natural rubber.\nSariling pagsusuri:Natutukoy ba ang mica at ceramic at hindi ginagarantiya ang paggamit mula sa pangalan lamang?',['Kapag may gasgas o pagbabago ng kulay sa insulation, huwag hawakan upang subukan ang kaligtasan; iulat ayon sa pamamaraan.','Huwag magpalit ng materyal o magkumpuni ng insulation nang walang pahintulot.'],'Magkakaiba ang papel ng conductive, magnetic, at insulating materials. Isama ang errata at sabay na tiyakin ang materyal at kondisyon ng paggamit.')
m.lesson(16,'Pagbasa ng resistor marking at tolerance','Kalkulahin ang four-band resistor code at hiwalay na tiyakin ang tolerance at rating.',[
('Hiwalay na pagbasa sa apat na band','Sa karaniwang four-band code, unang dalawa ang significant digits, ikatlo ang multiplier, at huli ang tolerance. Gamitin ang black0,brown1,red2,orange3,yellow4,green5,blue6,violet7,gray8,white9. Gold tolerance ay±5%,silver ay±10%.\nHuwag basta gamitin ito sa ibang bilang ng band o espesyal na marking. Kung malabo ang direksiyon o kahulugan, tingnan ang espesipikasyon. Iwasang tiyakin ang dating halaga mula lamang sa kulay na nagbago dahil sa pagkasunog.'),
('Nominal at saklaw','Ipinapakita ng tolerance ang pinapayagang paglihis sa nominal. Halimbawa,330 Ωna±5%ay330×0.05=16.5 Ωkaya313.5～346.5 Ωang kalkuladong saklaw. Sundin ang kondisyon ng pagsukat at espesipikasyon sa aktuwal na acceptance.\nKahit pareho ang resistance, maaaring iba ang power dissipation, temperatura, o sukat. Ang pagbasa sa color code lamang ay hindi patunay na maaaring ipalit ang ibang resistor.'),
('Hiwalay na halimbawa','Sa orange-orange-brown-gold,33ang significant digits,10¹ang multiplier,at±5%ang tolerance.33×10=330 Ωna maaari ring0.330 kΩ. Mali ang pagdugtong ng lahat ng digit bilang331 Ω. Ikatlong band ang nagtatakda ng pamparami, hindi digit na idudugtong.')],['Halagang ipinapakita bilang reference sa piyesa.','Saklaw ng pinapayagang paglihis sa reference.','Numerong ginagamit na pamparami.','Power na pinapayagan sa piyesa sa takdang kondisyon.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7kulay at tolerance,7kalkulasyon,3paglalagom.\nPagsulat:Basahin ang yellow-violet-red-gold bilang four-band at ipahayag saΩatkΩ. Kalkulahin ang±5%at magsulat ng dalawang espesipikasyong susuriin sa pagpapalit bukod sa resistance.\nSariling pagsusuri:Nakukuha ba ang47×100=4700 Ω=4.7 kΩat4465～4935 Ωat hiwalay na sinusuri ang power?',['Huwag sukatin ang resistance habang may kuryente; sundin ang power isolation at paghawak sa natitirang charge.','Huwag agad hawakan ang mainit na resistor o basta ipalit dahil lamang parehong halaga.'],'Ihiwalay ang significant digits,multiplier,at tolerance ng apat na band. Hiwalay na tiyakin ang resistance at rated power at ibang espesipikasyon.')
